      SUBROUTINE FNDSTPCC     LOCATE VARIABLE TO BE STEPPEDC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA1A.CIN'      INCLUDE 'DATA1C.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'DBEAM.CIN'      INCLUDE 'DBEND.CIN'      INCLUDE 'DCENT.CIN'      INCLUDE 'DCVTY.CIN'      INCLUDE 'DDRFT.CIN'      INCLUDE 'DETA.CIN'      INCLUDE 'DFIT.CIN'      INCLUDE 'DHKICK.CIN'      INCLUDE 'DKICK.CIN'      INCLUDE 'DMIS.CIN'      INCLUDE 'DOCT.CIN'      INCLUDE 'DQUAD.CIN'      INCLUDE 'DRBND.CIN'      INCLUDE 'DROT.CIN'      INCLUDE 'DSEXT.CIN'      INCLUDE 'DSOLE.CIN'      INCLUDE 'DSPEC.CIN'      INCLUDE 'DSROT.CIN'      INCLUDE 'ELM0A.CIN'      INCLUDE 'NELMS.CIN'      INTEGER         NBEAM, NROT, NDRFT, NBEND, NQUAD, NUPD      INTEGER         NCENT, NMIS, NREPS, NFIT, NCVTY, NCORR      INTEGER         NPRNT, NMTX, NUNIT, NSPEC, NORD, NSEXT      INTEGER         NSOLE, NSROT, NSTRA, NSTOR, NSECT, NOCT      INTEGER         NRAN, NETA, NRBND, NSBND, NMRKR, NHKCK      INTEGER         NPLT, NLIM, NMAGN, NSEPM, NKICK, NSHIFT      EQUIVALENCE     (NBEAM,NELMS(1)), (NROT ,NELMS(2)),     1                (NDRFT,NELMS(3)), (NBEND,NELMS(4)),     2                (NQUAD,NELMS(5)), (NUPD ,NELMS(6)),     3                (NCENT,NELMS(7)), (NMIS ,NELMS(8)),     4                (NREPS,NELMS(9)),  (NFIT ,NELMS(10)),     5                (NCVTY,NELMS(11)), (NCORR,NELMS(12)),     6                (NPRNT,NELMS(13)), (NMTX ,NELMS(14)),     7                (NUNIT,NELMS(15)), (NSPEC,NELMS(16)),     8                (NORD ,NELMS(17)), (NSEXT,NELMS(18)),     9                (NSOLE,NELMS(19)), (NSROT,NELMS(20)),     A                (NSTRA,NELMS(21)), (NSTOR,NELMS(22)),     B                                   (NSECT,NELMS(24)),     C                (NOCT ,NELMS(25)), (NRAN ,NELMS(26)),     D                (NETA ,NELMS(27)), (NRBND,NELMS(28)),     E                (NSBND,NELMS(29)),     F                (NMRKR,NELMS(31)),     H                (NHKCK,NELMS(35)),     I                                   (NPLT,NELMS(38)),     J                (NLIM ,NELMS(39)), (NMAGN,NELMS(40)),     K                (NSEPM,NELMS(41)), (NKICK,NELMS(42)),     L                (NSHIFT,NELMS(43))      INCLUDE 'STEPT1.CIN'      INCLUDE 'STEPTC.CIN'C      CHARACTER*15    LABLEC      IPAR = 0      IHIGH = 0C      DO 500 N = 1, NEL      IF (IPAR .NE. 0) GO TO 510      I = ISTOR(N)      IF (I .LT. IHIGH) GO TO 500      TYPE = IDATA(I)      LABLE = LABEL(N)      IF (LABLE .NE. STCTYP) GO TO 500      IELEM = I      CALL SKETCH(N)C      GO TO ( 10, 20, 30, 40, 50,500, 70, 80,500,100,     1       110,500,500,500,500,160,500,180,190,200,     2       500,500,500,500,250,500,270,280,280,300,     3       500,500,500,340,350,350,500,500,500,500,     4       500,420,500,500,500,500,500,500), TYPEC   10 CALL RDLOOK(STCPAR,15,DBEAM,1,NBEAM,IPAR)      GO TO 500C   20 CALL RDLOOK(STCPAR,15,DROT,1,NROT,IPAR)      GO TO 500C   30 CALL RDLOOK(STCPAR,15,DDRFT,1,NDRFT,IPAR)      GO TO 500C   40 CALL RDLOOK(STCPAR,15,DBEND,1,NBEND,IPAR)      GO TO 500C   50 CALL RDLOOK(STCPAR,15,DQUAD,1,NQUAD,IPAR)      GO TO 500C   70 CALL RDLOOK(STCPAR,15,DCENT,1,NCENT,IPAR)        GO TO 500C   80 CALL RDLOOK(STCPAR,15,DMIS,1,NMIS,IPAR)      GO TO 500C  100 CALL RDLOOK(STCPAR,15,DFIT,1,NFIT,IPAR)      GO TO 500C  110 CALL RDLOOK(STCPAR,15,DCVTY,1,NCVTY,IPAR)      GO TO 500C  160 CALL RDLOOK(STCPAR,15,DSPEC,1,NCORR,IPAR)       IF (IPAR .NE. 0) IPAR = 2      GO TO 500C  180 CALL RDLOOK(STCPAR,15,DSEXT,1,NSEXT,IPAR)      GO TO 500C  190 CALL RDLOOK(STCPAR,15,DSOLE,1,NSOLE,IPAR)      GO TO 500C  200 CALL RDLOOK(STCPAR,15,DSROT,1,NSROT,IPAR)      GO TO 500C  250 CALL RDLOOK(STCPAR,15,DOCT,1,NOCT,IPAR)      GO TO 500C  270 CALL RDLOOK(STCPAR,15,DETA,1,NRAN,IPAR)      GO TO 500C  280 CALL RDLOOK(STCPAR,15,DRBND,1,NRBND,IPAR)      GO TO 500C  300 IPAR = 1      GO TO 500C  340 CALL RDLOOK(STCPAR,15,DQUAD,1,NQUAD,IPAR)      GO TO 500C  350 CALL RDLOOK(STCPAR,15,DHKICK,1,NHKCK,IPAR)      GO TO 500C  420 CALL RDLOOK(STCPAR,15,DKICK,1,NKICK,IPAR)      GO TO 500C  500 CONTINUEC  510 ISTEP = IELEM + IPAR      RETURN      END